# deco113 · 10 món đồ trang trí mới (bản vẽ để anh Ares duyệt, chưa ship)
# Giá trải từ rẻ tới rất mắc, nhắm người chơi dư xu (bot dư ~118.000 xu ngày 30):
#   rẻ: đèn bão 250, lu nước mưa 450, bù nhìn rơm 900
#   vừa: bộ ván ngựa 2.200, giàn bông giấy 3.500
#   mắc: cối xay lúa 6.000, xuồng ba lá 9.000, giếng gạch có tời 14.000
#   rất mắc: chòi lá có võng 25.000, miếu Ông Địa 45.000
# Dùng: python3 deco113.py live/v112a.html live/v113d.html
import sys
src, dst = sys.argv[1], sys.argv[2]
s = open(src, encoding='utf-8').read()
def rep(a, b, n=1):
    global s
    c = s.count(a); assert c == n, (a[:90], c, n); s = s.replace(a, b)

rep("ghe_da: { cat: 'k', name: 'Ghế đá', price: 150 },",
    "ghe_da: { cat: 'k', name: 'Ghế đá', price: 150 }, bu_nhin_do: { cat: 'k', name: 'Bù nhìn áo đỏ ca rô', price: 1300, tier: 1 }, bu_nhin_hoa: { cat: 'k', name: 'Bù nhìn áo bông', price: 1600, tier: 1 }, den_sao: { cat: 'k', name: 'Đèn ông sao trụ tre', price: 500, tier: 1 }, lu_mua: { cat: 'k', name: 'Lu hứng nước mưa', price: 700, tier: 1 }, bu_nhin: { cat: 'k', name: 'Bù nhìn rơm', price: 1000, tier: 1 }, van_ngua: { cat: 'k', name: 'Bộ ván ngựa, bình trà', price: 2200, tier: 2 }, gian_bg: { cat: 'k', name: 'Vòm bông giấy', price: 3500, tier: 2 }, coi_xay: { cat: 'k', name: 'Cối xay lúa', price: 6000, tier: 3 }, xuong: { cat: 'k', name: 'Xuồng chở bông trên ao', price: 9000, tier: 3, b4: 1 }, gieng: { cat: 'k', name: 'Giếng cần vọt', price: 14000, tier: 3, b4: 1, up: 1.3 }, choi_la: { cat: 'k', name: 'Chòi lá có võng', price: 25000, tier: 4, b4: 1 }, mieu: { cat: 'k', name: 'Miếu Ông Địa', price: 45000, tier: 4, b4: 1 },")

