rep("function dcBuild(k, lite){ const tmp = new T.Group(); DCLITE = lite ? 1 : 0; const m = dcModel(k); DCLITE = 0; tmp.add(m); const ms = mergeMeshes(tmp), g = DYN(new T.Group()); for (const x of ms) g.add(x); return g; }", "function dcBuild(k, lite){ const tmp = new T.Group(); DCLITE = lite ? 1 : 0; DCH = []; const m = dcModel(k), hs = DCH; DCH = null; DCLITE = 0; if (DCK[k] && DCK[k].cat === 'k'){ const b4 = DCK[k].b4, bb = new T.Box3().setFromObject(m), sz = bb.getSize(new T.Vector3()), c0 = bb.getCenter(new T.Vector3()), kk = Math.min((DCK[k] && DCK[k].up) || 1, (b4 ? 2.62 : 1.3) / sz.x, (b4 ? 2.05 : 1.08) / sz.z); m.scale.setScalar(kk); m.position.x -= c0.x * kk; m.position.z -= c0.z * kk; for (const h of hs){ h.x = (h.x - c0.x) * kk; h.y *= kk; h.z = (h.z - c0.z) * kk; h.r *= kk; } } tmp.add(m); const ms = mergeMeshes(tmp), g = DYN(new T.Group()); for (const x of ms) g.add(x); const km = new Map(); tmp.traverse(o => { if (!o.isMesh || !o.userData.keep) return; const g0 = o.geometry.index ? o.geometry.toNonIndexed() : o.geometry.clone(); for (const n of Object.keys(g0.attributes)) if (n !== 'position' && n !== 'normal') g0.deleteAttribute(n); if (!g0.attributes.normal) g0.computeVertexNormals(); g0.clearGroups(); g0.applyMatrix4(o.matrixWorld); if (!km.has(o.material)) km.set(o.material, []); km.get(o.material).push(g0); }); for (const [mt, list] of km){ const mm = new T.Mesh(mergeGeometries(list, false), mt); mm.castShadow = true; g.add(mm); } dcFx(g, hs); return g; }")
