rep("if (!has(c - 1, r)) seg(u0 - h, v0 - ha, u0 - h, v1 + hb);", "if (!has(c - 1, r)) seg(u0 - BK, has(c, r - 1) ? v0 - Z.rg / 2 : v0 - BK, u0 - BK, v1 + hb);")
