rep("for (const i of own){ const c = i % Z.cols, r = Math.floor(i / Z.cols), [u0, v0, u1, v1] = PL[z.pre + (i + 1)].b;", "const curb = (ax, az, bx, bz) => { const len = Math.hypot(bx - ax, bz - az), ang = -Math.atan2(bz - az, bx - ax), n = Math.max(1, Math.round(len / .3)); M(box(len, .05, .1), '#8A6A3A', (ax + bx) / 2, .025, (az + bz) / 2, { r: [0, ang, 0], cast: false, sway: 0 }); for (let k = 0; k <= n; k++){ const t = k / n; M(cyl(.024, .028, .1, 5), '#B8925A', ax + (bx - ax) * t, .05, az + (bz - az) * t, { cast: false, sway: 0 }); } }; for (const i of own){ const c = i % Z.cols, r = Math.floor(i / Z.cols), [u0, v0, u1, v1] = PL[z.pre + (i + 1)].b;")
