rep("const on = ownCell(a) || ownCell(b); if (!on || cov.has(a + '|' + b)) continue; segs.push([a, b, c === Z.cols - 1]);", "const on = ownCell(a) || ownCell(b); if (!on || cov.has(a + '|' + b)) continue; const bedA = ownCell(a) && !locked(PL[a]), bedB = ownCell(b) && !locked(PL[b]); if (!bedA && !bedB && !(ownCell(a) && ownCell(b))) continue; segs.push([a, b, c === Z.cols - 1, bedA || bedB]);")
