for k_, old_, new_ in [('lu_da_luon',80,300),('den_long',90,350),('bong_giay',100,400),('ghe_da',150,400),('vong',120,450),('ban_ghe_tre',140,500),('cauvua',100,500),('nguyetque',110,600),('sudo',130,800),('kimquyt',140,900),('vantue',160,1100),('mai_chieu_thuy',120,1400),('hon_non_bo',260,1600),('cong_tre',200,1800),('sanh',180,1800),('cong_gach',500,4000)]:
    import re as _re
    s, n_ = _re.subn(k_ + r": \{ cat: 'k', name: '([^']+)', price: " + str(old_) + r" \}", lambda m: k_ + ": { cat: 'k', name: '" + m.group(1) + "', price: " + str(new_) + " }", s); assert n_ == 1, k_
