rep("const decoAt = id => (ST.dc.items || []).findIndex(it => it.at === id);", "const decoAt = id => (ST.dc.items || []).findIndex(it => it.at === id || (DCK[it.k] && DCK[it.k].b4 && (block4(it.at) || []).includes(id)));\nconst dcCells = it => (DCK[it.k] && DCK[it.k].b4 && block4(it.at)) || [it.at];\nfunction dcFit(id, it, k){ const P = PL[id]; if (!P || !P.bai) return null; const [Z, pre] = ZGRID[zoneOf(P)], i = +id.slice(1) - 1; for (const d of [0, 1, Z.cols, Z.cols + 1]){ const j = i - d; if (j < 0) continue; const B = block4(pre + (j + 1)); if (B && B.includes(id) && B.every(x => sapFree(x, it))) return B; } return null; }")
