rep("if (decoAt(id) >= 0 && !(it && it.t === 'dc' && id === it.from)) return false;", "{ const di0 = decoAt(id); if (di0 >= 0 && !(it && it.t === 'dc' && it.from && di0 === decoAt(it.from))) return false; }")
rep("if (di >= 0) return { t: 'dc', k: ST.dc.items[di].k, from: id };", "if (di >= 0) return { t: 'dc', k: ST.dc.items[di].k, from: ST.dc.items[di].at };")
